section.script:
document.addEventListener('DOMContentLoaded', function() {
    const productSelector = document.getElementById('product_selector');
    const variantSection = document.getElementById('variant_section');
    const variantSelector = document.getElementById('variant_selector');
    const payButton = document.getElementById('pay_button');
    const productImageSection = document.getElementById('product_image_section');
    const productImage = document.getElementById('product_image');
    const productName = document.getElementById('product_name');
    const selectedProductInput = document.getElementById('selected_product_id');

    productSelector.addEventListener('change', function() {
        const productId = this.value;
        const hasVariants = this.options[this.selectedIndex].dataset.hasVariants === 'True';
        const selectedOption = this.options[this.selectedIndex];

        if (productId) {
            // Mostrar imagen del producto
            const imageUrl = '/web/image/product.template/' + productId + '/image_1920';
            productImage.src = imageUrl;
            productName.textContent = selectedOption.textContent;
            productImageSection.style.display = 'block';

            if (hasVariants) {
                // Cargar variantes
                fetch('/my/get_product_variants/' + productId, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    body: JSON.stringify({})
                })
                .then(response => response.json())
                .then(response => {
                    const variants = response.result || response;

                    variantSelector.innerHTML = 'Selecciona modalidad...';

                    if (Array.isArray(variants)) {
                        variants.sort((a, b) => a.name.localeCompare(b.name));

                        variants.forEach(variant => {
                            if (variant.product_variant_ids && variant.product_variant_ids.length > 0) {
                                const option = document.createElement('option');
                                option.value = variant.product_variant_ids[0];
                                option.textContent = variant.name;
                                variantSelector.appendChild(option);
                            }
                        });
                    }
                    variantSection.style.display = 'block';
                })
                .catch(error => {
                    console.error('Error loading variants:', error);
                });
                payButton.disabled = true;
            } else {
                // Sin variantes, funcionalidad actual
                variantSection.style.display = 'none';
                selectedProductInput.value = productId;
                payButton.disabled = false;
            }
        } else {
            variantSection.style.display = 'none';
            productImageSection.style.display = 'none';
            selectedProductInput.value = '';
            payButton.disabled = true;
        }
    });

    variantSelector.addEventListener('change', function() {
        payButton.disabled = !this.value;
    });

    payButton.addEventListener('click', function(e) {
        const productId = productSelector.value;
        const hasVariants = productSelector.options[productSelector.selectedIndex].dataset.hasVariants === 'True';

        if (hasVariants) {
            e.preventDefault();
            const variantId = variantSelector.value;
            const variantText = variantSelector.options[variantSelector.selectedIndex].textContent;
            if (variantId) {
                const url = '/my/redirect_add_to_cart/' + variantId + '?variant_text=' + encodeURIComponent(variantText);
                window.open(url, '_blank');
            }
        }
        // Si no tiene variantes, el form se envía normalmente
    });
});

