                })
                .catch(error => {
                    console.error('Error loading variants:', error);
                });
                payButton.disabled = true;
            } else {
                // Sin variantes, habilitar pago directo
                variantSection.style.display = 'none';
                payButton.disabled = false;
            }
        } else {
            variantSection.style.display = 'none';
            productImageSection.style.display = 'none';
            payButton.disabled = true;
        }
    });

    variantSelector.addEventListener('change', function() {
        payButton.disabled = !this.value;
    });

    payButton.addEventListener('click', function(e) {
        const productId = productSelector.value;
        const hasVariants = productSelector.options[productSelector.selectedIndex].dataset.hasVariants === 'True';

        if (hasVariants) {
            e.preventDefault();
            const variantId = variantSelector.value;
            const variantText = variantSelector.options[variantSelector.selectedIndex].textContent;
            if (variantId) {
                const url = '/my/redirect_add_to_cart/' + variantId + '?variant_text=' + encodeURIComponent(variantText);
                window.open(url, '_blank');
            }
        } else {
            window.open('/my/certificates?titulacion=1&product_id=' + productId, '_blank');
        }
    });
});

